package com.burthorpesellcalc;

import net.runelite.api.*;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

public class burthorpemenuswapper {
    private final Client client;
    private final burthorpecalcplugin plugin;
    private final ItemManager itemManager;

    private int lastTrackedWorld = -1;
    private final Set<Integer> worldSoldItemIds = new HashSet<>();

    @Inject
    public burthorpemenuswapper(Client client, burthorpecalcplugin plugin, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.itemManager = itemManager;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGGING_IN) {
            worldSoldItemIds.clear();
            lastTrackedWorld = client.getWorld();
        }
    }

    @Subscribe
    public void onClientTick(ClientTick event) {
        if (client.isMenuOpen()) {
            return;
        }

        int currentWorld = client.getWorld();
        if (currentWorld != lastTrackedWorld && currentWorld != 0) {
            worldSoldItemIds.clear();
            lastTrackedWorld = currentWorld;
        }

        Menu rootMenu = client.getMenu();
        MenuEntry[] menuEntries = rootMenu.getMenuEntries();
        if (menuEntries == null || menuEntries.length == 0) {
            return;
        }

        MenuEntry defaultLeftClickSlot = menuEntries[menuEntries.length - 1];
        if (defaultLeftClickSlot == null) {
            return;
        }

        int rawItemId = defaultLeftClickSlot.getItemId();
        int canonicalId = itemManager.canonicalize(rawItemId);

        if (!plugin.isItemIncluded(canonicalId)) {
            return;
        }

        boolean itemHasShopStock = false;
        Widget shopGrid = client.getWidget(301, 16);

        if (shopGrid == null || shopGrid.isHidden()) {
            shopGrid = client.getWidget(300, 16);
        }

        if (shopGrid != null && !shopGrid.isHidden()) {
            Widget[] items = shopGrid.getDynamicChildren();
            if (items != null && items.length > 0) {
                for (Widget itemWidget : items) {
                    if (itemWidget != null && itemManager.canonicalize(itemWidget.getItemId()) == canonicalId) {
                        if (itemWidget.getItemQuantity() > 0) {
                            itemHasShopStock = true;
                            break;
                        }
                    }
                }
            }
        }

        int targetAmount = 1;
        Integer forcedBatch = plugin.getForcedBatchSize(canonicalId);
        if (forcedBatch != null) {
            targetAmount = forcedBatch;
        }

        boolean isSellAllMode = (targetAmount == burthorpecalcplugin.SELL_AMOUNT_ALL);
        int nativeLookupAmount = isSellAllMode ? 50 : targetAmount;

        // Bypasses overstock logic completely for Sell All mode
        if (!isSellAllMode) {
            if (!itemHasShopStock) {
                worldSoldItemIds.remove(canonicalId);
            }
            if (worldSoldItemIds.contains(canonicalId) || itemHasShopStock) {
                return;
            }
        }

        ItemContainer inventory = client.getItemContainer(93);
        if (inventory == null) {
            return;
        }

        MenuEntry nativeTargetOption = null;
        String regexPattern = "^Sell " + nativeLookupAmount + "\\b";
        Pattern pattern = Pattern.compile(regexPattern);

        for (MenuEntry entry : menuEntries) {
            String option = entry.getOption();
            if (option != null && pattern.matcher(option).find() && entry.getItemId() == rawItemId) {
                nativeTargetOption = entry;
                break;
            }
        }

        if (nativeTargetOption != null) {
            String coloredOptionText;
            if (isSellAllMode) {
                coloredOptionText = "<col=ff0000>Sell All (50s)</col>";
            } else {
                switch (targetAmount) {
                    case 1: coloredOptionText = "<col=00ffff>Sell 1</col>"; break;
                    case 5: coloredOptionText = "<col=00ff00>Sell 5</col>"; break;
                    case 10: coloredOptionText = "<col=ffff00>Sell 10</col>"; break;
                    case 50: coloredOptionText = "<col=ff9800>Sell 50</col>"; break;
                    default: coloredOptionText = "Sell " + targetAmount; break;
                }
            }

            defaultLeftClickSlot.setOption(coloredOptionText);
            defaultLeftClickSlot.setIdentifier(nativeTargetOption.getIdentifier());
            defaultLeftClickSlot.setParam0(nativeTargetOption.getParam0());
            defaultLeftClickSlot.setParam1(nativeTargetOption.getParam1());
            defaultLeftClickSlot.setType(nativeTargetOption.getType()); // FIX: Retains target interaction packets directly

            if (!isSellAllMode) {
                defaultLeftClickSlot.onClick(e -> worldSoldItemIds.add(canonicalId));
            }
            rootMenu.setMenuEntries(menuEntries);
        }
    }
}

package com.burthorpesellcalc;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("burthorpesellcalc")
public interface burthorpecalcconfig extends Config {

    @ConfigSection(
            name = "Bank Tag Integration Info",
            description = "Information regarding Bank Tag integration. Right-click, reset this 'Bank Tag Guide' to reset infobox.",
            position = 0,
            closedByDefault = false
    )
    String integrationSection = "integrationSection";

    @ConfigItem(
            keyName = "tagNoticeText",
            name = "Bank Tag Guide",
            description = "",
            position = 1,
            section = "integrationSection"
    )
    default String tagNoticeBox() {
        return "Selected items are automatically imported to the 'shopscape' bank tag. Please create this tag in-game to ensure easy item access. Warning: excluding items in layout mode requires the layout to be enabled and disabled to apply.";
    }

    enum ValueFormatMode {
        ROUNDED("Rounded"),
        PRECISE("Precise");

        private final String name;

        ValueFormatMode(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @ConfigItem(
            keyName = "valueFormat",
            name = "Value Format",
            description = "Decide how gp values show within shift right-click and your bank header",
            position = 2
    )
    default ValueFormatMode valueFormat() {
        return ValueFormatMode.ROUNDED;
    }

    @ConfigItem(keyName = "shiftBankMenu", name = "Shift Right-click : Bank Menu", description = "Toggles Shift right-click options within the Bank", position = 3)
    default boolean shiftBankMenu() { return true; }

    @ConfigItem(keyName = "shiftInventoryMenu", name = "Shift Right-click : Inventory Menu", description = "Toggles Shift right-click options within the inventory", position = 4)
    default boolean shiftInventoryMenu() { return true; }

    @ConfigItem(keyName = "enableBankHighlight", name = "Enable Bank Highlight", description = "Toggles highlighting included items within the bank", position = 5)
    default boolean enableBankHighlight() { return true; }

    @ConfigItem(keyName = "enableInventoryHighlight", name = "Enable Shop Highlight", description = "Toggles highlighting included items within the shop", position = 6)
    default boolean enableInventoryHighlight() { return true; }

    @ConfigItem(keyName = "clearInclusionsToggle", name = "Clear Database", description = "Clear all included items and their sell quantities", position = 7)
    default boolean clearInclusionsToggle() { return false; }

    @ConfigItem(keyName = "includedItemIds", name = "", description = "", hidden = true)
    default String includedItemIds() { return ""; }

    @ConfigItem(keyName = "includedItemIds", name = "", description = "")
    void setIncludedItemIds(String val);
}

package com.burthorpesellcalc;

import com.google.inject.Provides;
import net.runelite.api.*;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.bank.BankSearch;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.text.NumberFormat;
import java.util.HashMap;
import java.util.Locale;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

@PluginDescriptor(
        name = "Burthorpe Shop Calculator",
        description = "Calculates shop sale yields and appends values seamlessly to the bank title text natively",
        tags = {"bank", "shop", "money", "calc", "ironman"}
)
public class burthorpecalcplugin extends Plugin {

    @Inject private Client client;
    @Inject private burthorpecalcconfig config;
    @Inject private ItemManager itemManager;
    @Inject private OverlayManager overlayManager;
    @Inject private burthorpeitemoverlay itemOverlay;
    @Inject private EventBus eventBus;
    @Inject private burthorpemenuswapper menuSwapper;
    @Inject private ConfigManager configManager;
    @Inject private ClientThread clientThread;
    @Inject private BankSearch bankSearch;

    private final Set<Integer> includedItems = new HashSet<>();
    private final Map<Integer, Integer> forcedSellTiers = new HashMap<>();

    private String cachedShopTextStr = "";

    public static final int SELL_AMOUNT_DEFAULT = 1;
    public static final int SELL_AMOUNT_LOW = 5;
    public static final int SELL_AMOUNT_MEDIUM = 10;
    public static final int SELL_AMOUNT_HIGH = 50;
    public static final int SELL_AMOUNT_ALL = -1;

    @Provides
    @SuppressWarnings("unused")
    burthorpecalcconfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(burthorpecalcconfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        loadInclusions();
        overlayManager.add(itemOverlay);
        eventBus.register(menuSwapper);
        syncAllIncludedTags();
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(itemOverlay);
        eventBus.unregister(menuSwapper);
        forcedSellTiers.clear();
        cachedShopTextStr = "";

        Widget bankTitleWidget = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (bankTitleWidget != null && bankTitleWidget.getText() != null) {
            String nativeText = bankTitleWidget.getText();
            nativeText = nativeText.replaceAll("\\s*<col=[0-9a-fA-F]+>\\(SHOP:[^)]+\\)\\s*\\(INV:[^)]+\\)</col>", "");
            bankTitleWidget.setText(nativeText);
        }
    }
    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals("burthorpesellcalc")) {
            return;
        }

        if (event.getKey().equals("clearInclusionsToggle")) {
            if (!config.clearInclusionsToggle()) {
                return;
            }

            if (configManager != null) {
                for (int id : includedItems) {
                    removeShopscapeTag(id);
                }
            }

            includedItems.clear();
            forcedSellTiers.clear();
            saveInclusions();
            recomputePricesCache();
            updateBankTitleValue();
            configManager.setConfiguration("burthorpesellcalc", "clearInclusionsToggle", false);
            redrawBankInterface();
        }

        if (event.getKey().equals("valueFormat")) {
            recomputePricesCache();
            updateBankTitleValue();
        }
    }

    public boolean isItemIncluded(int itemId) {
        return includedItems.contains(itemManager.canonicalize(itemId));
    }

    public Integer getForcedBatchSize(int itemId) {
        return forcedSellTiers.get(itemManager.canonicalize(itemId));
    }

    private void saveInclusions() {
        StringBuilder sb = new StringBuilder();
        for (int id : includedItems) {
            int tierValue = forcedSellTiers.getOrDefault(id, SELL_AMOUNT_DEFAULT);
            sb.append(id).append(":").append(tierValue).append(",");
        }
        config.setIncludedItemIds(sb.toString());
    }

    private void loadInclusions() {
        includedItems.clear();
        forcedSellTiers.clear();
        String stored = config.includedItemIds();
        if (stored == null || stored.isEmpty()) return;

        for (String entry : stored.split(",")) {
            if (!entry.trim().isEmpty()) {
                try {
                    if (entry.contains(":")) {
                        String[] parts = entry.split(":");
                        int itemId = Integer.parseInt(parts[0].trim());
                        int tierValue = Integer.parseInt(parts[1].trim());

                        includedItems.add(itemId);
                        forcedSellTiers.put(itemId, tierValue);
                    } else {
                        int itemId = Integer.parseInt(entry.trim());
                        includedItems.add(itemId);
                        forcedSellTiers.put(itemId, SELL_AMOUNT_DEFAULT);
                    }
                } catch (NumberFormatException ignored) {}
            }
        }
    }

    private void syncAllIncludedTags() {
        if (configManager == null || includedItems.isEmpty()) return;
        for (int id : includedItems) {
            addShopscapeTag(id);
        }
    }
    @Subscribe(priority = 1)
    public void onScriptPreFired(ScriptPreFired event) {
        if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING) {
            recomputePricesCache();
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event) {
        if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING) {
            updateBankTitleValue();
        }
    }

    private void recomputePricesCache() {
        ItemContainer bankContainer = client.getItemContainer(95);
        ItemContainer containerInv = client.getItemContainer(93);

        long totalBankValue = calculateContainerValue(bankContainer);
        long totalInvValue = calculateContainerValue(containerInv);

        String formattedShopStr = formatValue(totalBankValue);
        String formattedInvStr = formatValue(totalInvValue);

        cachedShopTextStr = " <col=ff981f>(SHOP: " + formattedShopStr + ") (INV: " + formattedInvStr + ")</col>";
    }

    public void updateBankTitleValue() {
        Widget bankTitleWidget = client.getWidget(InterfaceID.Bankmain.TITLE);
        if (bankTitleWidget == null || bankTitleWidget.isHidden() || cachedShopTextStr.isEmpty()) {
            return;
        }

        String nativeText = bankTitleWidget.getText();
        if (nativeText == null || nativeText.isEmpty()) {
            return;
        }

        String cleanText = nativeText.replaceAll("\\s*<col=[0-9a-fA-F]+>\\(SHOP:[^)]+\\)\\s*\\(INV:[^)]+\\)</col>", "");
        cleanText = cleanText.replaceAll("\\s*<col=[0-9a-fA-F]+>\\(SHOP:[^<]+\\)</col>", "");
        cleanText = cleanText.replaceAll("\\s*\\(SHOP:[^)]+\\)", "");

        bankTitleWidget.setText(cleanText + cachedShopTextStr);
    }

    private long calculateContainerValue(ItemContainer container) {
        if (container == null) return 0;

        long totalValue = 0;
        for (Item item : container.getItems()) {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
                continue;
            }

            int itemId = item.getId();
            if (!isItemIncluded(itemId)) {
                continue;
            }

            int batchSize = SELL_AMOUNT_DEFAULT;
            Integer forcedBatch = getForcedBatchSize(itemId);
            if (forcedBatch != null) {
                batchSize = forcedBatch;
            }

            if (batchSize == SELL_AMOUNT_ALL) {
                totalValue += calculateProjectedShopYield(itemId, item.getQuantity(), item.getQuantity());
            } else {
                totalValue += calculateProjectedShopYield(itemId, item.getQuantity(), batchSize);
            }
        }
        return totalValue;
    }

    public String formatValue(long value) {
        if (config.valueFormat() == burthorpecalcconfig.ValueFormatMode.PRECISE) {
            return NumberFormat.getNumberInstance(Locale.US).format(value);
        }

        if (value >= 1_000_000_000) {
            long truncated = value / 100_000_000;
            return (truncated / 10.0) + "B";
        }
        if (value >= 1_000_000) {
            long truncated = value / 100_000;
            return (truncated / 10.0) + "M";
        }
        if (value >= 1_000) {
            long truncated = value / 100;
            return (truncated / 10.0) + "K";
        }
        return String.valueOf(value);
    }

    public long calculateProjectedShopYield(int itemId, int totalQty, int sellBatchSize) {
        if (!isItemIncluded(itemId)) return 0;
        ItemComposition comp = itemManager.getItemComposition(itemId);
        int highAlchPrice = comp.getHaPrice();
        int baseStoreValue = comp.getPrice();
        if (highAlchPrice <= 0 || baseStoreValue <= 0) return 0;

        long totalCashYield = 0;
        int remainingItems = totalQty;

        int minimumFloorPrice = (int) Math.floor(baseStoreValue * 0.10);

        while (remainingItems > 0) {
            int currentBatch = Math.min(remainingItems, sellBatchSize);

            for (int i = 0; i < currentBatch; i++) {
                int decayedItemPrice = highAlchPrice - (int) Math.floor(i * 0.02 * baseStoreValue);

                if (decayedItemPrice < minimumFloorPrice) {
                    decayedItemPrice = minimumFloorPrice;
                }

                totalCashYield += decayedItemPrice;
            }

            remainingItems -= currentBatch;
        }
        return totalCashYield;
    }
    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (!client.isKeyPressed(KeyCode.KC_SHIFT) || event.getItemId() <= 0) {
            return;
        }

        MenuEntry entry = event.getMenuEntry();
        if (entry == null) return;

        String option = event.getOption();
        if (option == null) return;

        int packedWidgetId = event.getActionParam1();
        int widgetGroupId = packedWidgetId >> 16;

        boolean isBankVaultItem = (widgetGroupId == 12) && option.equals("Examine");
        boolean isInventoryItem = (widgetGroupId != 12) && option.equals("Examine");

        boolean bankAllowed = isBankVaultItem && config.shiftBankMenu();
        boolean inventoryAllowed = isInventoryItem && config.shiftInventoryMenu();

        if (!bankAllowed && !inventoryAllowed) {
            return;
        }

        MenuEntry[] existingEntries = client.getMenu().getMenuEntries();
        if (existingEntries != null) {
            for (MenuEntry existing : existingEntries) {
                String existingOpt = existing.getOption();
                if (existingOpt != null && (existingOpt.contains("Set (Sell -") || existingOpt.contains("Exclude from Shop"))) {
                    return;
                }
            }
        }

        int itemId = itemManager.canonicalize(event.getItemId());
        int totalStackQuantity = 0;

        Widget itemParent = client.getWidget(event.getActionParam1());
        if (itemParent != null) {
            Widget childItem = itemParent.getChild(event.getActionParam0());
            if (childItem != null && itemManager.canonicalize(childItem.getItemId()) == itemId) {
                totalStackQuantity = childItem.getItemQuantity();
            }
        }

        boolean naturallyIncluded = isItemIncluded(itemId);
        if (!naturallyIncluded) {
            includedItems.add(itemId);
            forcedSellTiers.put(itemId, SELL_AMOUNT_DEFAULT);
        }

        String yieldDefaultStr = formatValue(calculateProjectedShopYield(itemId, totalStackQuantity, SELL_AMOUNT_DEFAULT));
        String yieldLowStr = formatValue(calculateProjectedShopYield(itemId, totalStackQuantity, SELL_AMOUNT_LOW));
        String yieldMediumStr = formatValue(calculateProjectedShopYield(itemId, totalStackQuantity, SELL_AMOUNT_MEDIUM));
        String yieldHighStr = formatValue(calculateProjectedShopYield(itemId, totalStackQuantity, SELL_AMOUNT_HIGH));
        String yieldAllStr = formatValue(calculateProjectedShopYield(itemId, totalStackQuantity, totalStackQuantity));

        if (!naturallyIncluded) {
            includedItems.remove(itemId);
            forcedSellTiers.remove(itemId);
        }

        if (naturallyIncluded) {
            client.getMenu().createMenuEntry(-1)
                    .setOption("<col=d8b4fe>Exclude from Shop</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                    .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                    .onClick(e -> handleExclusionSelection(itemId));
        }

        client.getMenu().createMenuEntry(-1)
                .setOption("<col=ff0000>Set (Sell All)</col> <col=9e9e9e>[" + yieldAllStr + " GP]</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                .onClick(e -> handleForceSelection(itemId, SELL_AMOUNT_ALL));

        client.getMenu().createMenuEntry(-1)
                .setOption("<col=ff9800>Set (Sell - " + SELL_AMOUNT_HIGH + ")</col> <col=9e9e9e>[" + yieldHighStr + " GP]</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                .onClick(e -> handleForceSelection(itemId, SELL_AMOUNT_HIGH));

        client.getMenu().createMenuEntry(-1)
                .setOption("<col=ffff00>Set (Sell - " + SELL_AMOUNT_MEDIUM + ")</col> <col=9e9e9e>[" + yieldMediumStr + " GP]</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                .onClick(e -> handleForceSelection(itemId, SELL_AMOUNT_MEDIUM));

        client.getMenu().createMenuEntry(-1)
                .setOption("<col=00ff00>Set (Sell - " + SELL_AMOUNT_LOW + ")</col> <col=9e9e9e>[" + yieldLowStr + " GP]</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                .onClick(e -> handleForceSelection(itemId, SELL_AMOUNT_LOW));

        client.getMenu().createMenuEntry(-1)
                .setOption("<col=00ffff>Set (Sell - " + SELL_AMOUNT_DEFAULT + ")</col> <col=9e9e9e>[" + yieldDefaultStr + " GP]</col>").setTarget(event.getTarget()).setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier()).setParam0(event.getActionParam0()).setParam1(event.getActionParam1()).setItemId(itemId)
                .onClick(e -> handleForceSelection(itemId, SELL_AMOUNT_DEFAULT));
    }
    private void handleForceSelection(int itemId, int quantity) {
        int canonicalId = itemManager.canonicalize(itemId);

        includedItems.add(canonicalId);
        forcedSellTiers.put(canonicalId, quantity);
        saveInclusions();

        String oldTags = configManager.getConfiguration("banktags", "item_" + canonicalId);
        addShopscapeTag(canonicalId);
        String newTags = configManager.getConfiguration("banktags", "item_" + canonicalId);

        recomputePricesCache();
        updateBankTitleValue();

        ConfigChanged fluentEvent = new ConfigChanged();
        fluentEvent.setGroup("banktags");
        fluentEvent.setKey("item_" + canonicalId);
        fluentEvent.setOldValue(oldTags);
        fluentEvent.setNewValue(newTags);
        eventBus.post(fluentEvent);

        redrawBankInterface();
    }

    private void handleExclusionSelection(int itemId) {
        int canonicalId = itemManager.canonicalize(itemId);

        includedItems.remove(canonicalId);
        forcedSellTiers.remove(canonicalId);
        saveInclusions();

        String oldTags = configManager.getConfiguration("banktags", "item_" + canonicalId);
        boolean noTagsLeft = removeShopscapeTag(canonicalId);
        String newTags = noTagsLeft ? null : configManager.getConfiguration("banktags", "item_" + canonicalId);

        recomputePricesCache();
        updateBankTitleValue();

        ConfigChanged fluentEvent = new ConfigChanged();
        fluentEvent.setGroup("banktags");
        fluentEvent.setKey("item_" + canonicalId);
        fluentEvent.setOldValue(oldTags);
        fluentEvent.setNewValue(newTags);
        eventBus.post(fluentEvent);

        redrawBankInterface();
    }

    private void redrawBankInterface() {
        clientThread.invokeLater(() -> bankSearch.reset(false));
    }

    private void addShopscapeTag(int itemId) {
        if (configManager == null) return;
        String currentTags = configManager.getConfiguration("banktags", "item_" + itemId);
        if (currentTags == null || currentTags.isEmpty()) {
            configManager.setConfiguration("banktags", "item_" + itemId, "shopscape");
        } else {
            String cleanTags = currentTags.toLowerCase();
            if (!cleanTags.contains("shopscape")) {
                configManager.setConfiguration("banktags", "item_" + itemId, currentTags + ",shopscape");
            }
        }
    }

    private boolean removeShopscapeTag(int itemId) {
        if (configManager == null) return false;

        String currentTags = configManager.getConfiguration("banktags", "item_" + itemId);
        boolean standardWiped = true;

        if (currentTags != null && !currentTags.isEmpty()) {
            String[] tags = currentTags.split(",");
            StringBuilder sb = new StringBuilder();
            for (String tag : tags) {
                String trimmedTag = tag.trim();
                if (!trimmedTag.equalsIgnoreCase("shopscape")) {
                    if (sb.length() > 0) sb.append(",");
                    sb.append(trimmedTag.toLowerCase());
                }
            }

            if (sb.length() == 0) {
                configManager.unsetConfiguration("banktags", "item_" + itemId);
            } else {
                configManager.setConfiguration("banktags", "item_" + itemId, sb.toString());
                standardWiped = false;
            }
        }

        return standardWiped;
    }
}

package com.burthorpesellcalc;

import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

public class burthorpeitemoverlay extends WidgetItemOverlay {
    private final Client client;
    private final burthorpecalcplugin plugin;
    private final burthorpecalcconfig config;
    private final ItemManager itemManager;

    // Per-frame cached data to eliminate duplicate lookups
    private Widget activeShopGrid = null;
    private final Map<Integer, Integer> shopStockCache = new HashMap<>();

    @Inject
    public burthorpeitemoverlay(Client client, burthorpecalcplugin plugin, burthorpecalcconfig config, ItemManager itemManager) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.itemManager = itemManager;
        showOnBank();
        showOnInventory();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        // Look up active shop grid exactly once at the beginning of the frame
        activeShopGrid = client.getWidget(301, 16);
        if (activeShopGrid == null || activeShopGrid.isHidden()) {
            activeShopGrid = client.getWidget(300, 16); // Fallback layout variant
        }

        // Populate a fast lookup cache for current shop stock if a shop is open
        shopStockCache.clear();
        if (activeShopGrid != null && !activeShopGrid.isHidden()) {
            Widget[] shopItems = activeShopGrid.getDynamicChildren();
            if (shopItems != null) {
                for (Widget shopItemWidget : shopItems) {
                    if (shopItemWidget != null && shopItemWidget.getItemQuantity() > 0) {
                        int shopItemCanonicalId = itemManager.canonicalize(shopItemWidget.getItemId());
                        shopStockCache.put(shopItemCanonicalId, shopItemWidget.getItemQuantity());
                    }
                }
            }
        }

        // Delegate execution back to the base engine to process individual item slots
        return super.render(graphics);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, net.runelite.api.widgets.WidgetItem widgetItem) {
        int canonicalId = itemManager.canonicalize(itemId);
        if (!plugin.isItemIncluded(canonicalId)) {
            return;
        }

        int packedWidgetId = widgetItem.getWidget().getId();
        int widgetGroupId = packedWidgetId >> 16;

        // Structural check evaluating target context matching your plugin scripts
        boolean isBankWidget = (widgetGroupId == InterfaceID.Bankmain.TITLE >> 16);

        // Bank Highlight Guard
        if (isBankWidget && !config.enableBankHighlight()) {
            return;
        }

        // Inventory/Shop Highlight Guard
        if (!isBankWidget) {
            if (!config.enableInventoryHighlight()) {
                return;
            }

            // Early exit if no shop GUI is open using our pre-cached frame widget
            if (activeShopGrid == null || activeShopGrid.isHidden()) {
                return;
            }
        }

        int batchSize = 1;
        Integer forcedBatch = plugin.getForcedBatchSize(canonicalId);
        if (forcedBatch != null) {
            batchSize = forcedBatch;
        }

        // Overstock Check Optimization: Replaced O(N) loop with O(1) map lookup
        if (!isBankWidget && batchSize != burthorpecalcplugin.SELL_AMOUNT_ALL) {
            if (shopStockCache.containsKey(canonicalId)) {
                return;
            }
        }

        // FIX: Replaced deprecated InventoryID enum lookup with raw stable container integer allocations
        // 95 matches Bank item storage containers, 93 matches Inventory storage containers
        int containerId = isBankWidget ? 95 : 93;
        ItemContainer container = client.getItemContainer(containerId);
        if (container == null) {
            return;
        }

        Color strokeColor;
        if (batchSize == burthorpecalcplugin.SELL_AMOUNT_ALL) {
            strokeColor = Color.RED;
        } else {
            switch (batchSize) {
                case 1: strokeColor = Color.CYAN; break;
                case 5: strokeColor = Color.GREEN; break;
                case 10: strokeColor = Color.YELLOW; break;
                case 50: strokeColor = Color.ORANGE; break;
                default: strokeColor = Color.MAGENTA; break;
            }
        }

        BufferedImage itemOutlineImage = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), strokeColor);
        if (itemOutlineImage != null) {
            graphics.drawImage(itemOutlineImage, widgetItem.getCanvasLocation().getX(), widgetItem.getCanvasLocation().getY(), null);
        }
    }
}
